CREATE TABLE [sales].[SalesInvoiceReturns]([ReturnId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_SalesInvoiceReturns_Id] DEFAULT NEWSEQUENTIALID(),[ReturnNumber] NVARCHAR(50) NOT NULL,[InvoiceId] UNIQUEIDENTIFIER NOT NULL,[InvoiceItemId] UNIQUEIDENTIFIER NOT NULL,[Quantity] DECIMAL(18,4) NOT NULL,[RefundAmount] DECIMAL(18,2) NOT NULL,[Reason] NVARCHAR(250) NOT NULL,[ReturnDate] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_SalesInvoiceReturns_Date] DEFAULT SYSUTCDATETIME(),[Status] NVARCHAR(20) NOT NULL CONSTRAINT [DF_SalesInvoiceReturns_Status] DEFAULT 'COMPLETED',[CreatedBy] NVARCHAR(256) NULL,[CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_SalesInvoiceReturns_Created] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_SalesInvoiceReturns] PRIMARY KEY([ReturnId]),CONSTRAINT [UQ_SalesInvoiceReturns_Number] UNIQUE([ReturnNumber]),CONSTRAINT [FK_SalesInvoiceReturns_Invoice] FOREIGN KEY([InvoiceId]) REFERENCES [sales].[SalesInvoices]([InvoiceId]),CONSTRAINT [FK_SalesInvoiceReturns_Item] FOREIGN KEY([InvoiceItemId]) REFERENCES [sales].[SalesInvoiceItems]([InvoiceItemId]),CONSTRAINT [CK_SalesInvoiceReturns_Quantity] CHECK([Quantity]>0));
